content = open('scripts/build-nsis.sh').read()
# Replace unescaped variables with escaped ones
content = content.replace('!define NAME "Lexic"', '!define NAME "Lexic"')
content = content.replace('!define VERSION "${VERSION}"', '!define VERSION "${VERSION}"')
content = content.replace('!define PUBLISHER "Crazygiscool"', '!define PUBLISHER "Crazygiscool"')
content = content.replace('!define WEBSITE "https://github.com/Crazygiscool/Lexic"', '!define WEBSITE "https://github.com/Crazygiscool/Lexic"')
content = content.replace('!define INSTALLER_NAME "lexic-${VERSION}-windows-installer.exe"', '!define INSTALLER_NAME "lexic-${VERSION}-windows-installer.exe"')
content = content.replace('Name "\\${NAME} \${VERSION}"', 'Name "\\${NAME} \${VERSION}"')
content = content.replace('OutFile "\${REPO_ROOT}/dist/lexic-\${VERSION}-windows-installer.exe"', 'OutFile "\${REPO_ROOT}/dist/lexic-\${VERSION}-windows-installer.exe"')
content = content.replace('InstallDir "\$PROGRAMFILES64\\${NAME}"', 'InstallDir "\$PROGRAMFILES64\\${NAME}"')
content = content.replace('WriteRegStr HKLM "Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\${NAME}" "DisplayName" "\${NAME} \${VERSION}"', 'WriteRegStr HKLM "Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\${NAME}" "DisplayName" "\${NAME} \${VERSION}"')
content = content.replace('WriteRegStr HKLM "Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\${NAME}" "DisplayVersion" "\${VERSION}"', 'WriteRegStr HKLM "Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\${NAME}" "DisplayVersion" "\${VERSION}"')
content = content.replace('WriteRegStr HKLM "Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\${NAME}" "Publisher" "\${PUBLISHER}"', 'WriteRegStr HKLM "Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\${NAME}" "Publisher" "\${PUBLISHER}"')
content = content.replace('WriteRegStr HKLM "Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\${NAME}" "InstallLocation" "\$INSTDIR"', 'WriteRegStr HKLM "Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\${NAME}" "InstallLocation" "\$INSTDIR"')
content = content.replace('WriteRegStr HKLM "Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\${NAME}" "UninstallString" "\$INSTDIR\\Uninstall.exe"', 'WriteRegStr HKLM "Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\${NAME}" "UninstallString" "\$INSTDIR\\Uninstall.exe"')
content = content.replace('WriteRegStr HKLM "Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\${NAME}" "URLInfoAbout" "\${WEBSITE}"', 'WriteRegStr HKLM "Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\${NAME}" "URLInfoAbout" "\${WEBSITE}"')
content = content.replace('Delete "\$SMPROGRAMS\\${NAME}.lnk"', 'Delete "\$SMPROGRAMS\\${NAME}.lnk"')
open('scripts/build-nsis.sh', 'w').write(content)
print('done')